using System;
using System.Collections.Generic;
using UnityEngine;

namespace Soup.Runtime
{
    /// <summary>
    /// The base class for every node. Inherited classes should define any necessary serialized data as well as implement the virtual functions.
    /// </summary>
    [Serializable]
    public abstract class ANode
    {
        public const string DEFAULT_OUTPORT = "Out";

        /** Generated by the editor when the node is created. */
        [SerializeField, HideInInspector]
        private protected string m_id;
        public string Id => m_id;

        [SerializeField, HideInInspector]
        private List<OutportEdge> m_outports = new();
        
        /// <summary>
        /// Override this for any necessary runtime data that the node may need to use during OnNodeUpdate.
        /// </summary>
        public virtual NodeRuntimeState CreateRuntimeState() => new EmptyNodeRuntimeState();
        
        /// <summary>
        /// Called once when the Soup Flow Graph first enters this node. Usually reserved for any setup.
        /// </summary>
        public virtual void OnNodeEnter(NodeExecutionContext context) { }
        
        /// <summary>
        /// Called once per tick as long as this is the node that is currently active. Once the node exits this function no longer gets called.
        /// This never gets called on the same tick as OnNodeEnter.
        /// </summary>
        public virtual void OnNodeUpdate(NodeExecutionContext context) { }
        
        /// <summary>
        /// Called once when the node has indicated that it has finished. Usually reserved for any teardown.
        /// The node can indicate that it's finished in either OnNodeEnter or OnNodeUpdate by calling context.TraverseEdge(). 
        /// </summary>
        public virtual void OnNodeExit(NodeExecutionContext context) { }

        #region Outports
        /// <summary>
        /// Adds this node's outports. By default a node has one outport, DEFAULT_OUTPORT. Override this for any other outports.
        /// This gets called whenever a NodeView needs to get redrawn which is usually when the node's data changes.
        /// Once new outports are defined, it's up to the implementor to provide the correct outportId when calling context.TraverseEdge().
        /// </summary>
        public virtual void DefineOutports(List<OutportDefinition> outports)
        {
            outports.Add(new OutportDefinition(DEFAULT_OUTPORT, DEFAULT_OUTPORT));
        }

        public OutportEdge GetOutportEdge(string outportId)
        {
            if (string.IsNullOrEmpty(outportId))
            {
                return null;
            }

            for (int i = 0; i < m_outports.Count; i++)
            {
                OutportEdge edge = m_outports[i];
                if (edge != null && edge.OutportId == outportId)
                {
                    return edge;
                }
            }

            return null;
        }
        #endregion

        /** For editor use. */
        #if UNITY_EDITOR
        internal void SetId(string id)
        {
            m_id = id;
        }

        internal List<OutportEdge> Outports => m_outports;

        internal const string ID_FIELD_NAME = nameof(m_id);
        internal const string OUTPORTS_FIELD_NAME = nameof(m_outports);
        #endif
    }
}
